use super::*;use super::super::tests::{release_case,MemoryStore};
#[path="next_waiting_owner_test.rs"]mod owner;
#[test]fn startup_repair_started_review_expiry_does_not_gate_existing_selected_admission(){
 let now=Instant::now();let stamp=nt2_desktop_g0::connection_time::Stamp{sequence:1,started:now-Duration::from_secs(2)};let mut state=w::WaitingState{state:Some("started".into()),review_remaining_ms:Some(0),..Default::default()};assert!(validate_review(&state,stamp,now).is_ok());state.state=Some("waiting".into());assert!(validate_review(&state,stamp,now).is_err());state.review_remaining_ms=Some(1000);assert!(validate_review(&state,stamp,now).is_err());state.review_remaining_ms=Some(3000);assert!(validate_review(&state,stamp,now).is_ok());state.state=Some("started".into());state.review_remaining_ms=Some(3600001);assert!(validate_review(&state,stamp,now).is_err());state.review_remaining_ms=None;assert!(validate_review(&state,stamp,now).is_err());
}
pub(super) fn parked()->(Core<MemoryStore>,startup::WaitingMarker){
 let(mut c,p,_)=release_case();c.base="https://waiting.invalid".into();let g=c.game.as_ref().unwrap();let d=c.desktop.as_ref().unwrap();
 let s=startup::Scope{origin:c.base.clone(),service:c.service.clone(),service_epoch:c.epoch.clone(),account:d.account.clone(),device:c.device,desktop:d.id.clone(),desktop_epoch:d.epoch.clone(),room:c.room.as_ref().unwrap().room_id.clone().unwrap(),run:p.run.clone(),run_epoch:p.epoch.clone(),config:p.config,config_digest:"a".repeat(64),preparation:"preparation".into()};
 let b=startup::Prepared::stage(s,p.seed,p.world_policy,7,Instant::now()+Duration::from_secs(60)).unwrap();let mut claim=7u32.to_le_bytes().to_vec();claim.extend_from_slice(&[1;16]);let adapter=rejoin::ResumeStore(c.store.clone());let m=startup::persist(&adapter,&b,u64::from(p.seed),nt2_local_ws::owner::Id::OsProcess(7),[1;16],&claim).unwrap();
 let gold:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../packages/contracts/g3-waiting/golden.json"))).unwrap();let mut i:w::WaitingIntent=serde_json::from_value(gold["fixtures"][0]["json"]["waiting"]["intent"].clone()).unwrap();let s=b.scope();i.service_id=Some(s.service.clone());i.account_id=Some(s.account.clone());i.device_id=Some(s.device.to_string());i.preparation_id=Some(s.preparation.clone());i.preparation_service_epoch=Some(s.service_epoch.clone());i.original_desktop_id=Some(s.desktop.clone());i.original_desktop_epoch=Some(s.desktop_epoch.clone());i.room_id=Some(s.room.clone());i.run_id=Some(s.run.clone());i.run_epoch=Some(s.run_epoch.clone());i.config_revision=Some(s.config.try_into().unwrap());i.config_digest=Some(s.config_digest.clone());i.actual_seed=Some(m.actual_seed.clone());i.seed_policy=Some("shared-fixed".into());i.randomize_loot=Some(false);i.world_token=Some(hex(&g.owner.1));i.original_attachment_id=Some(g.session.attachment.clone());i.original_game_instance_id=Some(g.instance.clone());i.context_id=Some(hex(&g.owner.1));
 let mut j=journal::Journal::new(m.clone());j.current_attachment=i.original_attachment_id.clone();j.intent=Some(i);j.generation=1;j.proof=Some("p".repeat(43));journal::save(&adapter,s,&j).unwrap();
 c.native_diagnostics.lock().unwrap().rejoin.waiting_offered=Some((nt2_local_ws::owner::Id::OsProcess(7),m.clone()));c.native_diagnostics.lock().unwrap().rejoin.contact=Some(crate::pipe::rejoin::Contact{pid:nt2_local_ws::owner::Id::OsProcess(7),context:[9;16],association:*m.local_world.as_bytes(),actual:m.actual_seed.parse().unwrap()});(c,m)
}
async fn load(c:&mut Core<MemoryStore>){let until=Instant::now()+Duration::from_secs(3);while c.waiting.contact.is_none(){assert!(Instant::now()<until);assert!(c.waiting_tick().await.unwrap());tokio::task::yield_now().await;}}
#[test]fn waiting_cold_restore_uses_protected_same_world_and_only_collection_lease(){tauri::async_runtime::block_on(async{
 let(mut c,m)=parked();let old=c.game.clone().unwrap();load(&mut c).await;let p=c.pending.lock().unwrap().clone().unwrap();assert_eq!(p.owner,Some((crate::local_owner::Id::os_process(7),[9;16])));assert_eq!(p.actual_seed,Some(424242));assert!(p.accepted);assert!(!p.loaded&&!p.release);assert!(p.claim_path.is_none());assert!(c.preparation.is_none());assert!(c.game.is_none());assert!(c.waiting.recover.is_none(),"No service recovery without current native protected observation");assert!(c.native_authority_valid(&p));assert_eq!(c.waiting_local_world(),Some(m.local_world));assert_eq!(c.waiting_world(),Some(hex(&old.owner.1).as_str()));
 let mut game=old;game.owner=(nt2_local_ws::owner::Id::OsProcess(7),[9;16]);c.game=Some(game);let ctx=c.connection_context().unwrap();assert_eq!(ctx.world,hex(&[1;16]));assert!(!ctx.recovered);assert!(ctx.original_start.is_none()&&ctx.participant.is_none()&&ctx.ownership.is_none(),"Waiting generation must not enter admitted generation");
 c.generation.fetch_add(1,Ordering::AcqRel);assert!(!c.native_authority_valid(&p));assert!(c.waiting_tick().await.is_err());
});}
#[test]fn waiting_wrong_seed_foreign_account_and_offline_never_restore_authority(){tauri::async_runtime::block_on(async{
 let(mut c,_)=parked();c.native_diagnostics.lock().unwrap().rejoin.contact.as_mut().unwrap().actual+=1;let until=Instant::now()+Duration::from_secs(3);loop{match c.waiting_tick().await{Err(e)=>{assert!(e.contains("contact differs"));break},Ok(_)=>{assert!(Instant::now()<until);tokio::task::yield_now().await;}}}assert!(c.waiting.contact.is_none());
 let(mut c,m)=parked();load(&mut c).await;let s=c.waiting.loaded.as_ref().unwrap().scope.clone();c.continue_offline().unwrap();assert!(startup::recall(&rejoin::ResumeStore(c.store.clone()),&s.origin,&s.service,&s.account,s.device,&m).unwrap().is_none());assert!(c.pending.lock().unwrap().as_ref().is_none_or(|p|!p.release));assert!(c.waiting_startup_marker().is_none());
 let(mut c,_)=parked();c.desktop.as_mut().unwrap().account="foreign".into();let until=Instant::now()+Duration::from_secs(3);loop{match c.waiting_tick().await{Err(_)=>break,Ok(_)=>{assert!(Instant::now()<until);tokio::task::yield_now().await;}}}assert!(c.waiting.loaded.is_none());assert!(c.waiting.contact.is_none());
});}
